window.addEventListener("DOMContentLoaded",function(){let e=document.getElementById("images-resize");e.addEventListener("change",function(t){let n=document.getElementById("block-resize-settings").querySelectorAll("input");e.checked?n.forEach(e=>{e.setAttribute("required",!0)}):n.forEach(e=>{e.removeAttribute("required")})});let t=document.getElementById("images-width-threshold"),n=document.getElementById("images-width-max"),d=document.getElementById("images-height-threshold"),i=document.getElementById("images-height-max");t.addEventListener("keyup",function(){n.innerText=t.value.replace("px","")+"px"}),d.addEventListener("keyup",function(){i.innerText=d.value.replace("px","")+"px"})});